        return t

    def parse(self):
        node = self.or_expr()
        if self.i != len(self.toks):
            raise UsageError(f"--where: unexpected {self.toks[self.i][1]!r}")
        return node

    def or_expr(self):
        node = self.and_expr()
        while self.peek("kw", "or"):
            self.i += 1
            node = ("or", node, self.and_expr())
        return node

    def and_expr(self):
        node = self.not_expr()
        while self.peek("kw", "and"):
            self.i += 1
            node = ("and", node, self.not_expr())
        return node

    def not_expr(self):
        if self.peek("kw", "not"):
            self.i += 1
            return ("not", self.not_expr())
        return self.primary()

    def primary(self):
        if self.peek("punct", "("):
            self.i += 1
            node = self.or_expr()
            self.take("punct", ")", "')'")
            return node
        return self.test()

    def literal(self):
        t = self.peek()
        if t and (t[0] in ("string", "number") or (t[0] == "kw" and t[1] in ("true", "false"))):
            self.i += 1
            return t
