@dataclass(frozen=True)
class Locale:
    name: str
    decimal: str
    group: str
    group_sizes: tuple[int, ...]
    min_grouping: int
    minus: str
    date: str
    datetime: str
    true: str
    false: str


def available() -> list[str]:
    return sorted(p.stem for p in LOCALE_DIR.glob("*.json"))


